import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { buildApiUrl } from '../../../shared/api/api-url';
import { buildCourseSearchParams } from './mock/courses-api.params.utils';
import { UserStore } from '../../user/model/user.store';
import { LanguagePairsApiService } from '../../language-pair/api';
import type {
  CourseIndexEntry,
  CourseSearchCriteria,
  CourseSearchPage,
  CourseWithPrograms,
} from '../model';
import type {
  CourseCatalogPort,
  CourseExportBundle,
  CourseWritePayload,
  LessonWritePayload,
  ProgramWritePayload,
} from '../repository/course-catalog.port';
import type { ContentLanguage } from '../../card/model/card-index.types';
import type {
  CourseList,
  CourseResponse,
  CourseCreateRequest,
  CourseUpdateRequest,
} from '../../../shared/api/generated/models';

export type {
  CourseWritePayload,
  LessonWritePayload,
  ProgramWritePayload,
  CourseCatalogPort,
  CourseExportBundle,
} from '..';
export type { CourseIndexEntry, CourseWithPrograms } from '../model';

/** Backend DTO for a course. */
type BackendCourseDto = {
  id: number;
  title: string;
  courseDescription: string;
  authorId: number;
  languagePairId: number | null;
  published: boolean;
  createdAt: string;
  updatedAt: string;
};

/** Map backend DTO → CourseIndexEntry. */
function toIndexEntry(
  dto: BackendCourseDto,
  pairCache: Record<number, { known: ContentLanguage; learning: ContentLanguage }>,
): CourseIndexEntry {
  const cached = dto.languagePairId ? pairCache[dto.languagePairId] : null;
  return {
    id: String(dto.id),
    title: dto.title,
    authorId: String(dto.authorId),
    programCount: 0,
    published: dto.published,
    updatedAt: dto.updatedAt,
    languagePairSummary: dto.languagePairId ? String(dto.languagePairId) : '',
    knownLanguage: cached?.known ?? 'ru',
    learningLanguage: cached?.learning ?? 'en',
  };
}

@Injectable({ providedIn: 'root' })
export class CoursesApiService implements CourseCatalogPort {
  private readonly http = inject(HttpClient);
  private readonly userStore = inject(UserStore);
  private readonly languagePairsApi = inject(LanguagePairsApiService);

  private pairCache: Record<number, { known: ContentLanguage; learning: ContentLanguage }> = {};
  private pairCacheLoaded = false;

  private async ensurePairCache(): Promise<void> {
    if (this.pairCacheLoaded) return;
    try {
      const pairs = await this.languagePairsApi.listAll();
      for (const p of pairs) {
        this.pairCache[p.id] = {
          known: p.knownCode as ContentLanguage,
          learning: p.learningCode as ContentLanguage,
        };
      }
    } catch {
      this.pairCache[1] = { known: 'ru' as ContentLanguage, learning: 'en' as ContentLanguage };
    }
    this.pairCacheLoaded = true;
  }

  search(criteria: CourseSearchCriteria): Promise<CourseSearchPage> {
    return this.ensurePairCache().then(() =>
      firstValueFrom(
        this.http.get<CourseList>(buildApiUrl('/courses/search'), {
          params: buildCourseSearchParams(criteria),
        }),
      ).then((response) => {
        // Response: { data: CourseDto[], total }
        const dtos = response.data ?? [];
        const totalItems = response.total ?? dtos.length;
        const pageSize = criteria.page.pageSize;
        const page = criteria.page.page;
        const totalPages = pageSize > 0 ? Math.ceil(totalItems / pageSize) : 0;

        // Cast to BackendCourseDto for mapping
        const mapped = dtos.map((d: any) => toIndexEntry(d, this.pairCache));
        return { items: mapped, page, pageSize, totalItems, totalPages };
      }),
    );
  }

  getById(courseId: string): Promise<CourseWithPrograms> {
    return firstValueFrom(this.http.get<CourseResponse>(buildApiUrl(`/courses/${courseId}`))).then(
      (response) => response.data as unknown as CourseWithPrograms,
    );
  }

  create(payload: CourseWritePayload): Promise<CourseWithPrograms> {
    const body: Record<string, unknown> = {
      title: payload.title,
      courseDescription: payload.description,
      authorId: this.userStore.user().id,
      published: payload.published,
    };
    if (payload.programs && payload.programs.length > 0) {
      body['programs'] = payload.programs;
    }
    return firstValueFrom(
      this.http.post<CourseResponse>(
        buildApiUrl('/courses'),
        body as unknown as CourseCreateRequest,
      ),
    ).then((response) => response.data as unknown as CourseWithPrograms);
  }

  update(courseId: string, payload: CourseWritePayload): Promise<CourseWithPrograms> {
    const body = {
      title: payload.title,
      courseDescription: payload.description,
      published: payload.published,
    };
    return firstValueFrom(
      this.http.put<CourseResponse>(
        buildApiUrl(`/courses/${courseId}`),
        body as CourseUpdateRequest,
      ),
    ).then((response) => response.data as unknown as CourseWithPrograms);
  }

  delete(courseId: string): Promise<void> {
    return firstValueFrom(this.http.delete<void>(buildApiUrl(`/courses/${courseId}`))).then(
      () => undefined,
    );
  }

  findUsingScenario(scenarioId: string): Promise<readonly CourseIndexEntry[]> {
    return firstValueFrom(
      this.http.get<{ data: CourseIndexEntry[] }>(
        buildApiUrl(`/courses/by-scenario/${scenarioId}`),
      ),
    ).then((response) => response.data);
  }

  getBundle(courseId: string): Promise<CourseExportBundle> {
    return firstValueFrom(
      this.http.get<{ data: CourseExportBundle }>(buildApiUrl(`/courses/${courseId}/bundle`)),
    ).then((response) => response.data);
  }
}
